<script setup lang="ts">
import StateValue from '@/components/StateValue.vue'
import { computed } from 'vue'
import { artistKinds,artistStatuses,features,purposes,delegatedActions,artistEvidence,type ArtistRecord,type ArtistServiceDetail } from '@/api/modules/artists'
import { money,artistServiceKinds } from '@/api/modules/trade'
const props=defineProps<{record:ArtistRecord;service?:ArtistServiceDetail|null;disabled?:boolean;readEvidence?:string[]}>(),emit=defineEmits<{evidence:[id:string];copy:[text:string]}>()
const consent=computed(()=>props.record.kind==='CONSENT'?props.record.data:null),delegation=computed(()=>props.record.kind==='DELEGATION'?props.record.data:null),variant=computed(()=>['LOOK','VOICE'].includes(props.record.kind)?props.record.data as Extract<ArtistRecord,{kind:'LOOK'|'VOICE'}>['data']:null),listing=computed(()=>props.record.kind==='LISTING'?props.record.data:null),halo=computed(()=>props.record.kind==='HALO'?props.record.data:null),identity=computed(()=>props.record.kind==='IDENTITY'?props.record.data:null),appeal=computed(()=>props.record.kind==='APPEAL'?props.record.data:null),serviceData=computed(()=>props.record.kind==='SERVICE'?props.record.data:null)
const evidence=computed(()=>artistEvidence(props.record))
const date=(v:string|null)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'尚未确定'
</script>
<template>
 <article class="artist-record" data-testid="artists-record">
  <section class="supply-card"><div class="section-heading"><h2>{{artistKinds[record.kind]}}</h2><span class="supply-badge" data-testid="artists-record-status"><StateValue :code="record.current_status" :label="artistStatuses[record.current_status]"/></span></div><p class="muted">这份记录只适用于当前真人及其指定数字人；保存、审核、付款和交付分别记录。</p>
   <details class="ops-technical"><summary>核对这份记录的真人与数字人归属</summary><dl class="supply-facts"><div><dt>真人档案编号</dt><dd class="identifier">{{record.person_id}}</dd></div><div><dt>具体数字人</dt><dd class="identifier">{{record.avatar_id||'此项按真人办理'}}</dd></div></dl></details>
  </section>
  <section v-if="consent" class="supply-card"><h2>本人这次明确允许的用途</h2><dl class="supply-facts"><div><dt>形象与声音</dt><dd>{{consent.features.map(f=>features[f]).join('、')}}</dd></div><div><dt>用途</dt><dd>{{consent.purposes.map(p=>purposes[p]).join('、')}}</dd></div><div><dt>获准使用主体</dt><dd class="identifier">{{consent.grantee_party_id}}</dd></div><div><dt>地区</dt><dd>{{consent.territories.join('、')}}</dd></div><div><dt>开始 / 结束</dt><dd>{{date(consent.valid_from)}} — {{date(consent.valid_until)}}</dd></div></dl><p class="long-text">{{consent.terms}}</p><p class="muted">同意存私人档案，不等于允许公开展示、重新生成或制作其他项目；仍需核对相应用途和本次主体。</p></section>
  <section v-if="delegation" class="supply-card"><h2>机构代办范围</h2><dl class="supply-facts"><div><dt>受托机构</dt><dd class="identifier">{{delegation.organization_party_id}}</dd></div><div><dt>原MCN合作关系</dt><dd class="identifier">{{delegation.relation_id}}</dd></div><div><dt>允许代办的事项</dt><dd>{{delegation.actions.map(a=>delegatedActions[a]).join('、')}}</dd></div><div><dt>开始 / 结束</dt><dd>{{date(delegation.valid_from)}} — {{date(delegation.valid_until)}}</dd></div></dl><p class="long-text">{{delegation.terms}}</p><p class="muted">资料所有权仍归本人。机构不能替本人同意、代签或修改原佣金；材料读取仍单独核权。</p></section>
  <section v-if="variant" class="supply-card"><h2>{{record.kind==='LOOK'?'造型':'声音'}} · {{variant.display_name}}</h2><dl class="supply-facts"><div><dt>版本序号</dt><dd>{{variant.revision}}</dd></div><div><dt>上一版本</dt><dd class="identifier">{{variant.previous_version_id||'首次版本'}}</dd></div><div><dt>本版同意依据</dt><dd class="identifier">{{variant.consent_id}}</dd></div></dl><p class="muted">本版材料及同意分别保存。不能用另一份有效同意恢复已经撤回或不可用的原材料版本。</p></section>
  <section v-if="listing" class="supply-card"><h2>{{listing.display_name}} · 公开展示申请</h2><p>{{listing.city}} · {{listing.tags.join(' / ')}}</p><p class="long-text">{{listing.introduction}}</p><dl class="supply-facts"><div><dt>试镜展示</dt><dd>{{listing.audition_public?'本申请另行开启':'本申请未开启'}}</dd></div><div><dt>公开同意依据</dt><dd class="identifier">{{listing.consent_id}}</dd></div><div><dt>造型版本</dt><dd class="identifier">{{listing.look_version_id}}</dd></div><div><dt>声音版本</dt><dd class="identifier">{{listing.voice_version_id||'本申请不展示声音'}}</dd></div></dl><p class="muted">目录只显示当前符合条件的已批准资料。每次预览仍核验本人同意、托管和展示状态。</p></section>
  <section v-if="identity" class="supply-card"><h2>受信实名服务返回</h2><p>{{identity.result?artistStatuses[identity.result.status]:'结果尚未核实，不作为已实名'}}</p><dl v-if="identity.result" class="supply-facts"><div><dt>年龄核验</dt><dd>{{identity.result.age_band==='ADULT'?'成年人':identity.result.age_band==='MINOR'?'未成年人，本轮不处理实际素材':'尚未核实'}}</dd></div><div><dt>结果有效期</dt><dd>{{date(identity.result.valid_until)}}</dd></div></dl><details class="ops-technical"><summary>核验服务引用</summary><p class="identifier">会话引用：{{identity.session_ref}}</p><p v-if="identity.result" class="identifier">核验方：{{identity.result.issuer}} · 回执：{{identity.result.evidence_ref}}</p></details></section>
  <section v-if="halo" class="supply-card"><h2>L{{halo.level}} 认证申请</h2><p>{{halo.level===1?'L1本人权属审核免费':'本次采用原审核服务，付款不代表审核通过'}}</p><dl class="supply-facts"><div><dt>原审核服务</dt><dd class="identifier">{{halo.service_id||'免费L1不关联收费服务'}}</dd></div><div><dt>认证有效期</dt><dd>{{date(halo.valid_from)}} — {{date(halo.valid_until)}}</dd></div></dl><p class="muted">补件沿用这一申请和原费用；L3真实业务指标尚未接入，不开放购买或人工升级。</p></section>
  <section v-if="appeal" class="supply-card"><h2>对原审核的异议</h2><p class="long-text">{{appeal.reason}}</p><dl class="supply-facts"><div><dt>原申请</dt><dd class="identifier">{{appeal.target_id}}</dd></div><div><dt>原申请内容校验值</dt><dd class="identifier">{{appeal.target_sha256}}</dd></div></dl><p class="muted">这份异议不会自动改写原拒绝记录。</p></section>
  <section v-if="serviceData" class="supply-card" data-testid="artists-service-details"><h2>{{artistServiceKinds[serviceData.kind]}}</h2><p class="trade-amount">{{money(serviceData.price_minor)}}</p><dl class="supply-facts"><div><dt>已审规格版本</dt><dd>{{serviceData.specification.version}} · {{serviceData.specification.service_tier}}</dd></div><div><dt>失败后可重试次数</dt><dd>{{serviceData.specification.service.retry_limit}}</dd></div><div><dt>实际已尝试次数</dt><dd>{{serviceData.attempts}}</dd></div><div><dt>自动扣款</dt><dd>未启用</dd></div><div v-if="serviceData.kind==='AVATAR_HOSTING'"><dt>续托管提醒</dt><dd>{{serviceData.renewal_reminder?'已开启提醒':'未开启提醒'}}</dd></div><div v-if="serviceData.specification.service.hosting_months"><dt>约定托管月数</dt><dd>{{serviceData.specification.service.hosting_months}}</dd></div></dl>
   <p class="long-text">{{serviceData.specification.terms}}</p><ul><li v-for="d in serviceData.specification.deliverables" :key="d">{{d}}</li></ul>
   <div class="artist-reference"><p>服务请求编号：<span class="identifier">{{record.id}}</span></p><button class="outline" type="button" @click="emit('copy',record.id)">复制服务请求编号</button><p>已审规格编号：<span class="identifier">{{serviceData.spec_id}}</span></p><button class="outline" type="button" @click="emit('copy',serviceData.spec_id)">复制已审规格编号</button></div>
   <RouterLink :to="'/trade/quotes/new?artistService='+record.id+'&personId='+record.person_id" class="button-link outline" data-testid="artists-service-quote">交由实际平台签约机构办理报价</RouterLink><p class="muted">本人提供服务请求和已审规格编号；报价仍由有权商户明确核对买方及商品，链接不授予报价或读取私人资料的权限。</p>
   <template v-if="service"><h3>服务关联的原订单</h3><template v-if="service.order"><RouterLink :to="'/trade/orders/'+service.order.id" class="button-link outline" data-testid="artists-original-order">查看本人获准的原订单</RouterLink><p>原订单已核实实收 {{money(service.order.financial.received_minor)}} · 已退 {{money(service.order.financial.refunded_minor)}} · 净额 {{money(service.order.financial.net_minor)}}</p></template><p v-else>尚未关联正式订单。服务申请不代表已付款、已签署或已交付。</p></template>
   <div v-if="serviceData.hosting_period"><h3>已核实托管有效期</h3><p>{{date(serviceData.hosting_period.valid_from)}} — {{date(serviceData.hosting_period.valid_until)}}</p><p class="muted">首次核实收款后起算，续期接已有期限；实际日期以服务记录为准，刷新或提醒不延长。</p></div>
   <div v-if="serviceData.last_failure"><h3>最近一次创建失败</h3><p class="long-text">{{serviceData.last_failure.reason}}</p><p class="muted">{{date(serviceData.last_failure.at)}}</p></div>
   <div v-if="serviceData.refund"><h3>{{record.current_status==='REFUNDED'?'原订单退款已核实':'原订单退款待办理'}}</h3><p>{{money(serviceData.refund.amount_minor)}} · {{serviceData.refund.verified_at?date(serviceData.refund.verified_at):'当前不是退款到账证明'}}</p><RouterLink :to="'/trade/orders/'+serviceData.refund.order_id" class="button-link outline">核对原交易退款</RouterLink></div>
   <div v-if="serviceData.delivery"><h3>已保存的服务结果</h3><p>{{serviceData.delivery.type==='DIGITAL_ARCHIVE'?'内部私人档案交付，长期模型仍未启用':serviceData.delivery.type==='HOSTING_ENTITLEMENT'?'托管权益已记录':'原认证审核服务已办理'}}</p><p class="muted">{{date(serviceData.delivery.at)}}</p><template v-if="serviceData.delivery.type==='DIGITAL_ARCHIVE'"><p class="identifier">档案校验值：{{serviceData.delivery.archive_sha256}}</p><div v-for="version in serviceData.delivery.archive.versions" :key="version.id" class="artist-item"><h4>{{version.kind==='LOOK'?'造型':'声音'}} · {{version.data.display_name}} · 第{{version.data.revision}}版</h4><p class="identifier">{{version.id}} · {{version.content_sha256}}</p></div></template></div>
  </section>
  <section v-if="evidence.length" class="supply-card"><h2>本记录明确引用的材料</h2><p class="muted">每次读取重新核权。机构不能因为受托经营而查看全部本人证明；运营只读取本申请获准的证据。</p><div v-for="assetId in evidence" :key="assetId" class="artist-evidence"><span class="identifier">{{assetId}}</span><button class="outline" type="button" :disabled="disabled" :data-testid="'artists-evidence-'+assetId" @click="emit('evidence',assetId)">读取这份指定材料</button><span v-if="readEvidence?.includes(assetId)" class="muted">本次已读取</span></div></section>
  <section v-if="record.data.review" class="supply-card"><h2>原独立审核结论</h2><p>{{record.data.review.decision==='APPROVE'?'已通过':record.data.review.decision==='REJECT'?'已拒绝':'要求补充材料'}}</p><p class="long-text">{{record.data.review.reason}}</p><p class="muted">{{date(record.data.review.reviewed_at)}}</p></section>
  <section v-if="record.data.supplements?.length" class="supply-card"><h2>原申请补件记录</h2><article v-for="(item,n) in record.data.supplements" :key="n" class="artist-item"><h3>第{{n+1}}次补充</h3><p class="long-text">{{item.note}}</p><p class="muted">{{date(item.at)}}</p><p v-if="item.previous_review" class="long-text">原要求：{{item.previous_review.reason}}</p></article></section>
  <section v-if="record.data.withdrawal" class="supply-card"><h2>已撤回的原约定</h2><p class="long-text">{{record.data.withdrawal.reason}}</p><p class="muted">{{date(record.data.withdrawal.at)}} · 已有合法历史记录按原规则保留。</p></section>
  <details class="ops-technical"><summary>本记录编号、版本及内容校验值</summary><dl class="supply-facts"><div><dt>记录编号</dt><dd class="identifier" data-testid="artists-record-id">{{record.id}}</dd></div><div><dt>当前版本</dt><dd>{{record.object_version}}</dd></div><div><dt>内容校验值</dt><dd class="identifier">{{record.content_sha256}}</dd></div><div><dt>提交账号</dt><dd class="identifier">{{record.created_by}}</dd></div></dl></details>
 </article>
</template>
